fn assistant_lines(text: &str, marker: &'static str, width: u16) -> Vec<Line<'static>> {
    let blocks = smash_ui::markdown::render(text, width.max(8) as usize);
    blocks
        .into_iter()
        .enumerate()
        .map(|(index, block)| {
            let mut spans: Vec<Span<'static>> = Vec::with_capacity(block.spans.len() + 2);
            spans.push(Span::raw(if index == 0 { marker } else { "  " }));
            if block.indent > 0 {
                spans.push(Span::raw(" ".repeat(block.indent)));
            }
            spans.extend(
                block
                    .spans
                    .into_iter()
                    .map(|span| Span::styled(span.text, ink_style(span.ink))),
            );
            Line::from(spans)
        })
        .collect()
}

